style.css:
@-moz-document domain("roblox.com") {
/* Buttons */
  button,
  .btn-primary,
  .btn-secondary,
  .btn-control,
  .btn-growth-sm,
  .btn-growth-lg {
    background-color: #a855f7 !important; /* Purple-500 */
    border-color: #9333ea !important;
  }

  /* On hover */
  button:hover,
  .btn-primary:hover,
  .btn-secondary:hover {
    background-color: #9333ea !important; /* Purple-600 */
    border-color: #7e22ce !important;
  }

  /* Icons, SVG fills, and interactive elements */
  svg,
  svg path,
  .icon,
  .icon svg {
    fill: #a855f7 !important;
    stroke: #a855f7 !important;
  }

  /* Tabs, sliders, progress bars, toggles, and accents */
  .tab,
  .tab-active,
  .progress-bar-fill,
  .slider-bar-fill,
  .toggle-active,
  .slider-track-fill {
    background-color: #a855f7 !important;
  }

  /* Notification dots and badges */
  .notification-badge,
  .notification-dot,
  .badge-count {
    background-color: #a855f7 !important;
    color: white !important;
  }

  /* Link hover underline */
  a:hover {
    text-decoration-color: #a855f7 !important;
  }

  /* Border accents */
  .border-accent,
  .border-highlight,
  .rbx-border {
    border-color: #a855f7 !important;
  }

  /* Active navigation item */
  .nav-item.active,
  .nav-item.selected,
  .menu-option.active {
    border-bottom: 3px solid #a855f7 !important;
  }

  /* Focus rings */
  :focus {
    outline-color: #a855f7 !important;
    box-shadow: 0 0 0 2px #a855f7 !important;
  }
}
